CREATE TABLE "dim_product_id" ("product_id" VARCHAR, "product_name" VARCHAR, "category" VARCHAR, "brand" VARCHAR, "unit_price" VARCHAR, PRIMARY KEY ("product_id"));
CREATE TABLE "dim_warehouse_id" ("warehouse_id" VARCHAR, "warehouse_name" VARCHAR, "warehouse_city" VARCHAR, "warehouse_postcode" VARCHAR, PRIMARY KEY ("warehouse_id"));
CREATE TABLE "dim_customer_id" ("customer_id" VARCHAR, "customer_name" VARCHAR, "customer_city" VARCHAR, "customer_segment" VARCHAR, PRIMARY KEY ("customer_id"));
CREATE TABLE "dim_order_id" ("order_id" VARCHAR, "order_date" VARCHAR, "order_status" VARCHAR, "sales_channel" VARCHAR, PRIMARY KEY ("order_id"));
CREATE TABLE "dim_product_id_warehouse_id" ("product_id" VARCHAR, "warehouse_id" VARCHAR, "bin_location" VARCHAR, "reorder_point" BIGINT, PRIMARY KEY ("product_id", "warehouse_id"));
CREATE TABLE "records" ("order_id" VARCHAR, "customer_id" VARCHAR, "line_number" BIGINT, "product_id" VARCHAR, "warehouse_id" VARCHAR, "quantity" BIGINT, "discount_percent" BIGINT, "delivery_note" VARCHAR, PRIMARY KEY ("order_id", "line_number"), FOREIGN KEY ("product_id") REFERENCES "dim_product_id" ("product_id"), FOREIGN KEY ("warehouse_id") REFERENCES "dim_warehouse_id" ("warehouse_id"), FOREIGN KEY ("customer_id") REFERENCES "dim_customer_id" ("customer_id"), FOREIGN KEY ("order_id") REFERENCES "dim_order_id" ("order_id"), FOREIGN KEY ("product_id", "warehouse_id") REFERENCES "dim_product_id_warehouse_id" ("product_id", "warehouse_id"));
CREATE VIEW dataset AS SELECT "records"."order_id" AS "order_id", "dim_order_id"."order_date" AS "order_date", "dim_order_id"."order_status" AS "order_status", "dim_order_id"."sales_channel" AS "sales_channel", "records"."customer_id" AS "customer_id", "dim_customer_id"."customer_name" AS "customer_name", "dim_customer_id"."customer_city" AS "customer_city", "dim_customer_id"."customer_segment" AS "customer_segment", "records"."line_number" AS "line_number", "records"."product_id" AS "product_id", "dim_product_id"."product_name" AS "product_name", "dim_product_id"."category" AS "category", "dim_product_id"."brand" AS "brand", "dim_product_id"."unit_price" AS "unit_price", "records"."warehouse_id" AS "warehouse_id", "dim_warehouse_id"."warehouse_name" AS "warehouse_name", "dim_warehouse_id"."warehouse_city" AS "warehouse_city", "dim_warehouse_id"."warehouse_postcode" AS "warehouse_postcode", "dim_product_id_warehouse_id"."bin_location" AS "bin_location", "dim_product_id_warehouse_id"."reorder_point" AS "reorder_point", "records"."quantity" AS "quantity", "records"."discount_percent" AS "discount_percent", "records"."delivery_note" AS "delivery_note" FROM records JOIN "dim_product_id" ON records."product_id" = "dim_product_id"."product_id" JOIN "dim_warehouse_id" ON records."warehouse_id" = "dim_warehouse_id"."warehouse_id" JOIN "dim_customer_id" ON records."customer_id" = "dim_customer_id"."customer_id" JOIN "dim_order_id" ON records."order_id" = "dim_order_id"."order_id" JOIN "dim_product_id_warehouse_id" ON records."product_id" = "dim_product_id_warehouse_id"."product_id" AND records."warehouse_id" = "dim_product_id_warehouse_id"."warehouse_id";
